import{_ as t,c as a,o as s,ai as o}from"./chunks/framework.Dnk5eX27.js";const p=JSON.parse('{"title":"metalstack.summit Munich","description":"","frontmatter":{"title":"metalstack.summit Munich","date":"2026-10-15","banner":"assets/events/20261015_metalstack.summit_banner.svg","bannerMobile":"assets/events/20261015_metalstack.summit_banner_mobile.svg","bannerSmall":"assets/events/20261015_metalstack.summit_banner_small.svg","backgroundhex":"#889aa4ff","tags":["neonephos","metalstack.summit"],"rssPubDate":"2026-09-01","published":true,"sidebar":false,"aside":false,"prev":false,"next":false,"layout":"EventEntryThemeComponent"},"headers":[],"relativePath":"events/2026_10_15_metalstack.summit.md","filePath":"events/2026_10_15_metalstack.summit.md"}'),n={name:"events/2026_10_15_metalstack.summit.md"};function r(i,e,l,m,c,u){return s(),a("div",null,e[0]||(e[0]=[o('<h2 id="metalstack-summit-2026" tabindex="-1">metalstack.summit 2026 <a class="header-anchor" href="#metalstack-summit-2026" aria-label="Permalink to &quot;metalstack.summit 2026&quot;">​</a></h2><p>The <strong>metalstack.summit 2026</strong>, hosted by <strong>NeoNephos member x-cellent technologies GmbH</strong>, will bring together developers, platform engineers, operators, and users of sovereign Kubernetes infrastructure to discuss modern cloud-native technologies and the future of bare-metal platforms. Taking place on <strong>October 15, 2026</strong>, the event focuses on practical experiences, open-source technologies, and real-world deployments of sovereign Kubernetes solutions built entirely on bare metal infrastructure.</p><h3 id="neonephos-at-metalstack-summit" tabindex="-1">NeoNephos at metalstack.summit <a class="header-anchor" href="#neonephos-at-metalstack-summit" aria-label="Permalink to &quot;NeoNephos at metalstack.summit&quot;">​</a></h3><p>We are pleased that <strong>Vasu Chandrasekhara</strong> will represent the <strong>NeoNephos Foundation</strong> with the talk:</p><h3 id="sovereignty-func-ecosystems-interoperability" tabindex="-1">Sovereignty = func(Ecosystems, Interoperability); <a class="header-anchor" href="#sovereignty-func-ecosystems-interoperability" aria-label="Permalink to &quot;Sovereignty = func(Ecosystems, Interoperability);&quot;">​</a></h3><p>The session explores a question that is becoming increasingly important for Europe: How can digital sovereignty be achieved without creating new silos? Drawing on lessons from the Draghi Report, IPCEI-CIS, and the development of the NeoNephos Foundation, the talk examines the role of vendor-neutral open source, interoperable standards, and foundation-led collaboration in building a competitive and sovereign digital ecosystem. Rather than competing within fragmented technology stacks, the presentation argues for the creation of a shared digital commons where organizations collaborate on the core while continuing to innovate and compete on top of common standards.</p><p>The session will also discuss how technologies such as Kubernetes and bare-metal cloud infrastructure contribute to portability, interoperability, and freedom of choice.</p><hr><p>📍 <strong>Location / Ort</strong>: x-cellent technologies GmbH, Rosenkavalierplatz 10, 81925 München</p><p>📅 <strong>Date / Datum</strong>: October 15 2026 / 15. Oktover 2026</p><p>🔗 Learn more and register: <a href="https://metalstack.cloud/de/lp/metalstack-summit-2026" target="_blank" rel="noreferrer">metalstack.summit</a></p>',11)]))}const d=t(n,[["render",r]]);export{p as __pageData,d as default};
